<div class="room-grid">@forelse($rooms as $room)<article class="room-card {{ $room->status }}"><div class="room-top"><span class="room-number">{{ $room->number }}</span><span class="badge {{ $room->status }}">{{ \App\Models\Room::STATUSES[$room->status] }}</span></div><p class="muted">{{ $room->floor }} ထပ် · {{ $room->type }} <span class="room-rate">{{ number_format($room->rate) }} K / ည</span></p><div class="room-guest">@if($room->activeStay)<a href="{{ route('stays.show',$room->activeStay) }}">{{ $room->activeStay->guest_name }} ↗</a><small>ထွက်ရန် {{ $room->activeStay->expected_check_out_at->format('d M · H:i') }}</small>@elseif($room->status === 'available')<span class="muted">ဧည့်သည်အသစ် လက်ခံနိုင်သည်</span>@elseif($room->status === 'dirty')<span class="muted">သန့်ရှင်းရေး ပြုလုပ်ရန်</span>@else<span class="muted">ပြင်ဆင်မှု ဆောင်ရွက်နေသည်</span>@endif</div><div class="room-actions">@if($room->status === 'available')<a class="btn secondary small" href="{{ route('stays.create',['room'=>$room->id]) }}">+ Check-in</a>@elseif($room->status === 'dirty')<form method="post" action="{{ route('rooms.status',$room) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="available"><button class="btn small">✓ အခန်းသန့်ပြီး</button></form>@elseif($room->activeStay)<a class="btn secondary small" href="{{ route('stays.show',$room->activeStay) }}">အသေးစိတ်ကြည့်ရန်</a>@endif @if(auth()->user()->isManager())<a class="text-link" href="{{ route('rooms.edit',$room) }}">ပြင်ရန်</a>@endif</div></article>@empty<div class="empty">ဤအခြေအနေရှိသောအခန်း မရှိသေးပါ။</div>@endforelse</div>